draw:
var Lm = 48, Rm = 16, Tm = 20, Bm = 34;
var a = p.a, b = p.b, m = p.m;
var U = function(x) { return a*x*x*x*x + b*x*x; };
var x0 = b >= 0 ? 0 : Math.sqrt(-b/(2*a));
var k2 = 12*a*x0*x0 + 2*b;
if (k2 < 0.01) k2 = 0.01;
var w = Math.sqrt(k2/m);
var xb = Math.max(1.6, 1.9*x0), xa = -xb;
var i, xs, us, umin = 1e9, umax = -1e9;
for (i = 0; i <= 200; i++) { xs = xa + (xb-xa)*i/200; us = U(xs); if (us < umin) umin = us; if (us > umax) umax = us; }
var pad = 0.15*(umax-umin) + 0.001; umin -= pad; umax += pad;
var px = function(x) { return Lm + (x-xa)/(xb-xa)*(W-Lm-Rm); };
var py = function(u) { return H-Bm - (u-umin)/(umax-umin)*(H-Tm-Bm); };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(Lm, py(umin)); ctx.lineTo(W-Rm, py(umin)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(px(0), Tm); ctx.lineTo(px(0), H-Bm); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("U (J)", 6, Tm + 2);
ctx.fillText("x (m)", W-Rm-34, H-Bm+16);
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath();
for (i = 0; i <= 200; i++) { xs = xa + (xb-xa)*i/200; if (i === 0) ctx.moveTo(px(xs), py(U(xs))); else ctx.lineTo(px(xs), py(U(xs))); }
ctx.stroke();
var A = 0.16*xb;
var half = 3*A;
ctx.strokeStyle = C.accent; ctx.lineWidth = 1.5; ctx.setLineDash([4,4]);
ctx.beginPath();
for (i = 0; i <= 80; i++) {
  xs = x0 - half + 2*half*i/80;
  us = U(x0) + 0.5*k2*(xs-x0)*(xs-x0);
  if (us > umax) us = umax;
  if (i === 0) ctx.moveTo(px(xs), py(us)); else ctx.lineTo(px(xs), py(us));
}
ctx.stroke();
ctx.setLineDash([]);
ctx.strokeStyle = C.rule; ctx.setLineDash([3,4]);
ctx.beginPath(); ctx.moveTo(px(x0), py(U(x0))); ctx.lineTo(px(x0), py(umin)); ctx.stroke();
ctx.setLineDash([]);
var xball = x0 + A*Math.cos(w*t);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(px(xball), py(U(xball)) - 5, 6, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("minimum at x = " + x0.toFixed(2), px(x0) - 40, H - Bm + 16);
ctx.fillStyle = C.accent;
ctx.fillText("parabola from U''", Lm + 6, Tm + 2);
out.note = "x0 = " + x0.toFixed(2) + " m,  U'' = " + k2.toFixed(2) + " N/m,  omega = " + w.toFixed(2) + " rad/s,  T = " + (6.2832/w).toFixed(2) + " s";
